import{_ as o,c as e,o as d,ag as a}from"./chunks/framework._xRlcm3f.js";const p=JSON.parse('{"title":"GitLab Hugo 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/gitlab-gitlabhugo.md","filePath":"platforms/gitlab-gitlabhugo.md","lastUpdated":1790228279000}'),s={name:"platforms/gitlab-gitlabhugo.md"};function i(c,t,r,l,n,g){return d(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="gitlab-hugo-配置指南" tabindex="-1">GitLab Hugo 配置指南 <a class="header-anchor" href="#gitlab-hugo-配置指南" aria-label="Permalink to &quot;GitLab Hugo 配置指南&quot;">​</a></h1><p>通过 <strong>GitLab API</strong> 将文章发布到 GitLab 上的 <strong>Hugo</strong> 站点仓库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可作为 Hugo 站点仓库的 <strong>GitLab 仓库</strong>（如 <code>hugo-blog</code>）。</li><li>一个对该仓库有 <strong>push 权限</strong> 的 <strong>GitLab 个人访问令牌（Personal Access Token）</strong>（GitLab 右上角头像 → Preferences → Access Tokens，或访问 <code>/-/user_settings/personal_access_tokens</code>，勾选 <code>api</code> 或 <code>write_repository</code> 范围）。</li><li>该仓库是一个标准 Hugo 项目（含 <code>hugo.toml</code> / <code>hugo.yaml</code> 与 <code>content/</code>、<code>static/</code> 目录）。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>你的 GitLab 实例地址（自建实例填自己的域名，如 <code>https://gitlab.example.com</code>），用于拼出仓库地址</td></tr><tr><td>API 地址</td><td>GitLab API 地址，<strong>与平台首页一致</strong>；填写平台首页后会自动同步为该地址，平台首页留空时该地址也会被清空</td></tr><tr><td>用户名</td><td>GitLab 用户名（owner），用于拼出仓库地址</td></tr><tr><td>鉴权 Token</td><td>GitLab 个人访问令牌（Personal Access Token），需对目标仓库有 push 权限</td></tr><tr><td>git 仓库名</td><td>Hugo 站点仓库名，与用户名组成 <code>&lt;user&gt;/&lt;repo&gt;</code>，如 <code>hugo-blog</code></td></tr><tr><td>默认分支</td><td>发布到的分支，默认 <code>main</code>，需与仓库实际分支一致</td></tr><tr><td>存储目录</td><td>Hugo 文章存储目录，默认 <code>content/post</code>。发布后的 <code>.md</code> 会写入该目录</td></tr><tr><td>文件规则</td><td>文章文件名规则，默认 <code>[slug].md</code>（文章别名）</td></tr><tr><td>文章预览规则</td><td>站点文章预览规则，默认 <code>/post/[postid].html</code>。Hugo 站点地址由站点配置的永久链接规则决定，此规则仅作查看参考</td></tr><tr><td>预览规则</td><td>GitLab blob 预览规则，固定 <code>/[user]/[repo]/blob/[branch]/[docpath]</code>，查看链接即该 <code>.md</code> 在仓库中的地址，<strong>不支持修改</strong></td></tr><tr><td>发布目录</td><td>默认 <code>content/post</code>。该平台<strong>不支持修改发布目录</strong>（配置页为只读提示），如需更换请删除账号后重新发布</td></tr><tr><td>YAML 永久链接</td><td>提供该开关；开启后把文章永久链接写入 Front Matter，供站点按自定义链接生成页面</td></tr><tr><td>图床</td><td>默认「当前平台」：图片提交到仓库 <code>static/images</code>，文章引用 <code>images/&lt;图片名&gt;</code></td></tr></tbody></table><p>发布写入的 Front Matter 含 <code>title</code>、<code>slug</code>、<code>date</code>、<code>lastmod</code>、<code>tags</code>、<code>categories</code>、<code>keywords</code>、<code>description</code>（可在「YAML 预设配置」中覆盖）。</p><p>「YAML 预设配置」留空时，Hugo 平台会写入以下默认值：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">toc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">isCJKLanguage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>填入 JSON 片段（例如 <code>{&quot;toc&quot;: false}</code>）时，改为逐键合并进 Front Matter。</p><h2 id="三、图片约定-hugo-静态资源目录" tabindex="-1">三、图片约定（Hugo 静态资源目录） <a class="header-anchor" href="#三、图片约定-hugo-静态资源目录" aria-label="Permalink to &quot;三、图片约定（Hugo 静态资源目录）&quot;">​</a></h2><ul><li><code>imageStorePath = static/images</code> 是<strong>仓库根目录</strong>下的固定路径（不随文章目录变化），图片提交到该目录。</li><li>Hugo 构建时会把 <code>static/</code> 下的资源<strong>原样输出</strong>到站点根目录，因此图片在站点上的地址是 <code>/images/&lt;图片名&gt;</code>。</li><li><code>imageLinkPath = images</code> 生成的引用为 <code>images/&lt;图片名&gt;</code>，构建产物中能正确解析到图片。</li><li>发布带图文章后，仓库中会同时出现 <code>content/post/&lt;文件名&gt;.md</code> 与 <code>static/images/&lt;图片名&gt;</code>。</li></ul><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 令牌、仓库、分支校验通过 → 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 GitLab Hugo → 发布。文章 <code>.md</code> 提交到 <code>content/post/[slug].md</code>。</li><li>「查看文章」打开仓库 blob 地址；站点线上地址由 Hugo 构建决定，需站点已构建部署。</li><li>带图发布时图片提交到 <code>static/images</code>，文章引用 <code>images/&lt;图片名&gt;</code>。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证通过但发布失败</strong>：确认个人访问令牌对目标仓库有 push 权限（<code>api</code> 或 <code>write_repository</code> 范围），仓库名与分支填写正确。权限不足会收到 401/403。</li><li><strong>自建 GitLab 该怎么填平台首页</strong>：平台首页填你的实例地址（如 <code>https://gitlab.example.com</code>），API 地址会同步为该地址；令牌地址同样由实例地址拼出（<code>/-/user_settings/personal_access_tokens</code>），需在你自己实例的偏好设置里生成令牌。</li><li><strong>图片要怎么发布</strong>：图床默认「当前平台」，图片提交到仓库 <code>static/images</code>，文章中引用 <code>images/&lt;图片名&gt;</code>；Hugo 构建时把 <code>static/</code> 原样复制到站点根，构建产物能正常显示。</li><li><strong>查看链接打不开</strong>：查看链接为仓库中该 <code>.md</code> 的 blob 地址（<code>/[user]/[repo]/blob/[branch]/[docpath]</code>），仓库中存在该文件即可打开，需已登录 GitLab 且对该仓库有访问权限；该规则固定，不支持修改。</li><li><strong>发布目录能不能改</strong>：不能，固定为存储目录（默认 <code>content/post</code>）；如需更换请删除账号后重新发布。</li><li><strong>线上没有新文章</strong>：Hugo 是通过构建（<code>hugo</code>）从仓库内容生成站点的，仅推送 <code>.md</code> 不会直接改变已部署站点；确认仓库已配置自动构建（GitLab CI / Pages 等）并触发一次构建。</li><li><strong>更新与删除</strong>：点「更新」会重新提交该文章并产生一次新提交；「删除」会移除仓库中对应的 <code>.md</code>，站点需重新构建才会同步下线。</li></ul>`,16)])])}const u=o(s,[["render",i]]);export{p as __pageData,u as default};
